ALLOWED = {'CREATED': {'VALIDATED'}, 'VALIDATED': {'PAYMENT_PENDING'}, 'PAYMENT_PENDING': {'PAYMENT_CONFIRMED'}, 'PAYMENT_CONFIRMED': {'COMPLETED'}}
def transition(snapshot, target, expected_version):
    if snapshot['version'] != expected_version:
        raise RuntimeError('version conflict')
    if target not in ALLOWED.get(snapshot['state'], set()):
        raise ValueError('illegal transition')
    return {**snapshot, 'state': target, 'version': expected_version + 1}
